SELECT id AS "id!: _", project_id AS "project_id!: _", attempt_id AS "attempt_id!: _", stage, run_number, state, science_revision, tester_id, spec AS "spec!: JsonbText", deadline_seconds, created_at AS "created_at!: DeferredTimestamp", claimed_by_service AS "claimed_by_service: _", via_channel, via_client, lease_generation, lease_token_hash, lease_expires_at AS "lease_expires_at: DeferredTimestamp", claimed_at AS "claimed_at: DeferredTimestamp", deadline AS "deadline: DeferredTimestamp", finished_at AS "finished_at: DeferredTimestamp", evidence_id AS "evidence_id: _", manifest_id AS "manifest_id: _", error_step, error_code, error_reason, logs AS "logs!: JsonbText", origin, previous_run_id AS "previous_run_id: _" FROM jobs WHERE attempt_id = $1 AND stage = $2
            ORDER BY run_number DESC LIMIT 1
